import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:sehatak/app_router.dart';import 'package:sehatak/core/models/women/women_models.dart';import 'package:sehatak/core/services/women_service.dart';class WomenClinicsScreen extends StatelessWidget{const WomenClinicsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('عيادات صحة المرأة')),body:StreamBuilder<List<WomenClinic>>(stream:WomenService().streamClinics(limit:20),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ListTile(onTap:()=>c.push(AppRouter.womenClinicDetail.replaceFirst(':id',d.id)),leading:const Icon(Icons.local_hospital,color:Color(0xFF9C27B0)),title:Text(d.name),subtitle:Text('${d.type} • ${d.address}'),trailing:Text(d.isOpen?'مفتوح':'مغلق')))).toList());}));}}
